params.script_inline:
import sys, json
doc = json.load(sys.stdin)
env = doc.get("envelope") or {}
header = env.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}
body = doc.get("body") or {}
params = doc.get("params") or {}
path = str(params.get("log_path") or "")
line = {"route": str(hop.get("route") or ""), "hop": hop, "context": ctx,
        "reply_to": str(env.get("reply_to") or ""), "body": body}
if path:
    with open(path, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(line, sort_keys=True) + "\n")
out = []
if hop.get("route") == "command_pin":
    pin = {"header": {"route": "pin"}, "messages": [], "pins": body.get("pins") or []}
    if "replace_sources" in body:
        pin["replace_sources"] = body["replace_sources"]
    out.append(pin)
sys.stdout.write(json.dumps(out))
